import os
import msal

class IdentityClient:
    def __init__(self, tenant_id: str, client_id: str, client_secret: str):
        self.tenant_id = tenant_id
        self.client_id = client_id
        self.client_secret = client_secret
        self.authority = f"https://login.microsoftonline.com/{self.tenant_id}"
        self.app = msal.ConfidentialClientApplication(
            self.client_id,
            authority=self.authority,
            client_credential=self.client_secret
        )

    def get_msal_app(self):
        return self.app

def get_identity_client_config():
    return {
        "tenant_id": os.environ.get("AZURE_AD_TENANT_ID", "YOUR_AZURE_AD_TENANT_ID"),
        "client_id": os.environ.get("AZURE_AD_CLIENT_ID", "YOUR_AZURE_AD_CLIENT_ID"),
        "client_secret": os.environ.get("AZURE_AD_CLIENT_SECRET", "YOUR_AZURE_AD_CLIENT_SECRET"),
    }

import os
from google.cloud import translate_v2 as translate

def translate_consent_copy(text: str, target_language: str = "en", source_language: str = "auto") -> dict:
    # Initialize Google Cloud Translation API client
    # Ensure GOOGLE_APPLICATION_CREDENTIALS environment variable is set

    try:
        client = translate.Client()

        if source_language == "auto":
            result = client.translate(text, target_language=target_language)
        else:
            result = client.translate(text, target_language=target_language, source_language=source_language)

        return {
            "original_text": text,
            "translated_text": result['translatedText'],
            "source_language": result['detectedSourceLanguage'] if source_language == "auto" else source_language,
            "target_language": target_language
        }

    except Exception as e:
        return {"error": f"Google Cloud Translation API error: {e}"}

import os
from pymongo import MongoClient
from datetime import datetime

def record_login_audit_event(user_id: str, event_type: str, details: dict) -> dict:
    # Initialize MongoDB Atlas client
    # Ensure MONGODB_ATLAS_URI environment variable is set

    mongo_uri = os.environ.get("MONGODB_ATLAS_URI", "mongodb+srv://<username>:<password>@<cluster-name>.mongodb.net/myDatabase?retryWrites=true&w=majority")
    database_name = os.environ.get("MONGODB_DATABASE_NAME", "federated_login_audit")
    collection_name = os.environ.get("MONGODB_COLLECTION_NAME", "login_events")

    if "<username>" in mongo_uri or "<password>" in mongo_uri:
        raise ValueError("MONGODB_ATLAS_URI environment variable must be properly configured with credentials.")

    try:
        client = MongoClient(mongo_uri)
        db = client[database_name]
        collection = db[collection_name]

        event_record = {
            "timestamp": datetime.utcnow(),
            "user_id": user_id,
            "event_type": event_type,
            "details": details
        }

        result = collection.insert_one(event_record)

        client.close()

        return {"status": "success", "inserted_id": str(result.inserted_id)}

    except Exception as e:
        return {"status": "error", "message": f"Failed to record audit event in MongoDB Atlas: {e}"}
